<!-- I1 Invite: what a friend sees from the link. One button, private, no No (SRS-RES-1, -5, -8). -->
<script lang="ts">
  import Screen from "../components/Screen.svelte";
  import Button from "../components/Button.svelte";
  import CountRing from "../components/CountRing.svelte";
  import InfoLines from "../components/InfoLines.svelte";
  import Icon from "../components/Icon.svelte";
  import Tip from "../components/Tip.svelte";
  import Flame from "../components/Flame.svelte";
  import { t } from "#lib/copy/index.ts";
  import type { InviteInfo, Theme } from "../components/parts";
  let {
    view = "kindling",
    theme = "light",
    info = null,
    have = 1,
    quorum = 2,
    error = "",
    busy = false,
    sample = false,
    canCondition = true,
    onyes,
    oncondition,
    onclose,
  }: {
    view?: "kindling" | "loading" | "missing-key" | "lit" | "gone";
    theme?: Theme;
    info?: InviteInfo | null;
    have?: number;
    quorum?: number;
    error?: string;
    busy?: boolean;
    sample?: boolean;
    canCondition?: boolean;
    onyes?: () => void;
    oncondition?: () => void;
    onclose?: () => void;
  } = $props();
  const host = $derived(info?.host ?? "");
  const where = $derived(
    info
      ? info.walkMin !== null
        ? t("invite.whereWalk", { host, spot: info.spot, walk: t("invite.walk", { min: info.walkMin }) })
        : t("invite.where", { host, spot: info.spot })
      : "",
  );
</script>

<Screen {theme} sound {onclose} title={host ? t("invite.title", { host }) : ""} heading={view === "loading" ? t("app.loading") : ""}
  stage={(view === "kindling" || view === "lit") && !!info} backdrop={info?.photo ?? ""} backdropAlt={info?.scene ?? ""}>
  {#snippet hero()}
    {#if info && (view === "kindling" || view === "lit")}
      <h1 class="t-invite words">{info.words}</h1>
    {/if}
  {/snippet}
  {#if view === "loading"}
    <div class="skeleton print-sk" aria-hidden="true"></div>
    <div class="skeleton line" aria-hidden="true"></div>
    <div class="skeleton line short" aria-hidden="true"></div>
  {:else if view === "missing-key"}
    <div class="center">
      <Icon name="warning" size={48} />
      <h1 class="t-title">{t("invite.missingKey")}</h1>
      {#if host}<p class="t-muted">{t("invite.missingKeyHelp", { host })}</p>{/if}
    </div>
  {:else if view === "gone"}
    <div class="center">
      <Flame state="gone" size={120} />
      <h1 class="t-title">{t("gone.title")}</h1>
      <p class="t-muted">{t("gone.body")}</p>
    </div>
  {:else if info}
    <Tip id="invite" text="tip.invite" />
    <div class="where">
      <Icon name="hotspots" size={22} />
      <div>
        <p>{where}</p>
        {#if info.met}
          <p class="spark t-small"><Icon name="spark" size={18} /><span>{t("invite.metHere", { n: info.met.times })}{#if info.met.line} {t("invite.sparkQuote", { line: info.met.line })}{/if}</span></p>
        {/if}
      </div>
    </div>
    <CountRing {have} {quorum} lit={view === "lit"} />
    <InfoLines access={info.access} nature={info.nature} compact />
    {#if error}<p class="err" role="alert">{error}</p>{/if}
  {/if}
  {#snippet actions()}
    {#if (view === "kindling" || view === "lit") && info}
      <Button icon="here" haptic="tap" loading={busy} onclick={onyes}>{t("invite.yes")}</Button>
      {#if canCondition}<Button variant="text" onclick={oncondition}>{t("invite.condition")}</Button>{/if}
    {:else if view === "missing-key" || view === "gone"}
      <Button variant="secondary" onclick={onclose}>{t("gone.close")}</Button>
    {/if}
  {/snippet}
</Screen>

<style>
  .words { margin: 0; font-size: calc(2.5rem * var(--text-scale)); line-height: 1.08; max-width: 14ch; }
  .where { display: flex; gap: 8px; align-items: flex-start; }
  .where p { margin: 0; }
  .spark { display: flex; gap: 6px; align-items: center; color: var(--accent-text); font-weight: 700; margin-top: 4px !important; }
  .center { flex: 1; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 10px; text-align: center; }
  .center h1, .center p { margin: 0; max-width: 22ch; }
  .err { margin: 0; color: var(--text); font-weight: 700; }
  .skeleton { background: color-mix(in srgb, var(--text) 9%, transparent); border-radius: var(--r-md); animation: pulse 1.4s var(--ease-in-out) infinite; }
  .print-sk { height: 300px; }
  .line { height: 32px; }
  .short { width: 60%; }
  @keyframes pulse { 50% { opacity: 0.55; } }
  @media (prefers-reduced-motion: reduce) { .skeleton { animation: none; } }
</style>
<!--
  The photo moment. The picture develops like an instant print: it starts as warm
  blank paper, then the image rises from pale sepia to full color over
  --dur-develop (2.4 s), matching the ~3 s the hub takes to draft the six words.
  state: blank | developing | developed. Reduced motion shows the final print at once.
  `scene` is a short description used as the image's accessible name (SRS-ACC-5).
  Motion (docs/design/motion.md 3.4): only opacity animates (animated blur is a known
  slow path in iOS Safari). A white haze lifts first, the sepia veil clears from the
  middle, and the edges clear last, like a chemical print. No flash.
-->
<script lang="ts">
  import { t } from "#lib/copy/index.ts";
  import SampleScene from "./SampleScene.svelte";
  let {
    state = "developed",
    scene = "",
    src = "",
    height = 420,
    tilt = -1.2,
    sample = false,
  }: {
    state?: "blank" | "developing" | "developed";
    scene?: string;
    src?: string;
    height?: number;
    tilt?: number;
    /** Catalog only: the illustrated stand-in photo. The app always passes a real photo. */
    sample?: boolean;
  } = $props();
</script>

<figure class="print {state}" style:--tilt="{tilt}deg" style:height="{height}px">
  <div class="paper grain">
    <div class="image photo-art" role="img" aria-label={scene || t("invite.photoFallback")}>
      {#if src}
        <img {src} alt="" />
      {:else if sample}
        <SampleScene />
      {/if}
      {#if state === "developing"}
        <span class="veil" aria-hidden="true"></span>
        <span class="edge" aria-hidden="true"></span>
        <span class="haze" aria-hidden="true"></span>
      {/if}
    </div>
  </div>
</figure>

<style>
  .print { margin: 0; transform: rotate(var(--tilt)); transition: transform var(--dur-slow) var(--ease-spring); }
  .paper { height: 100%; padding: 12px 12px 44px; background: var(--c-birch-50); border-radius: 6px; box-shadow: var(--e-3); }
  .image { position: relative; width: 100%; height: 100%; overflow: hidden; border-radius: 3px; background: #efe6d4; }
  .image :global(img), .image :global(svg) { width: 100%; height: 100%; object-fit: cover; }
  .blank .image > :global(*) { opacity: 0; }
  .developed .image > :global(*) { opacity: 1; }
  .haze, .veil, .edge { position: absolute; inset: 0; pointer-events: none; }
  .haze { background: #fbf8f2; }
  .veil { background: #c9a36a; mix-blend-mode: multiply; }
  .edge { background: radial-gradient(120% 95% at 50% 50%, transparent 52%, #8a6a3e 100%); mix-blend-mode: multiply; }
  /* 2.4 s total: image 0 to 70%; haze lifts 0 to 60%; veil clears 20 to 85%; edges clear 45 to 100%. */
  .developing .image > :global(:not(span)) { animation: develop-img var(--dur-develop) var(--ease-in-out) both; }
  .developing .haze { animation: haze var(--dur-develop) var(--ease-out) both; }
  .developing .veil { animation: veil var(--dur-develop) var(--ease-in-out) both; }
  .developing .edge { animation: edge var(--dur-develop) var(--ease-in-out) both; }
  @keyframes develop-img { 0% { opacity: 0; } 70%, 100% { opacity: 1; } }
  @keyframes haze { 0% { opacity: 0.85; } 60%, 100% { opacity: 0; } }
  @keyframes veil { 0%, 20% { opacity: 0.9; } 85%, 100% { opacity: 0; } }
  @keyframes edge { 0%, 45% { opacity: 1; } 100% { opacity: 0; } }
  @keyframes fade { from { opacity: 0; } to { opacity: 1; } }
  /* Reduced motion: the finished print fades in over 160 ms; no layers. */
  @media (prefers-reduced-motion: reduce) {
    .developing .image > :global(:not(span)) { animation: fade var(--dur-fade) linear both; }
    .haze, .veil, .edge { display: none; }
  }
  :global([data-reduce-motion]) .developing .image > :global(:not(span)) { animation: fade var(--dur-fade) linear both; }
  :global([data-reduce-motion]) .haze, :global([data-reduce-motion]) .veil, :global([data-reduce-motion]) .edge { display: none; }
</style>

