1	// Photo-fit hooks for the photo screens (I1, H2, H3). Each loads its module on first use, so
2	// the entry bundles carry only these lines: the light check on the photo's load event, and
3	// the full-screen viewer on tap.
4	export const lit = (e: Event) => import("./photo-light.ts").then((m) => m.light(e.currentTarget as HTMLImageElement));
5	export const zoom = (e: Event) => {
6	  const b = e.currentTarget as HTMLElement;
7	  const img = b.querySelector("img");
8	  if (img) import("./photo-view.ts").then((m) => m.openPhoto(img, b));
9	};

