p='apps/web/test/e2e/photo-fit.ts'
s=open(p).read()
def rep(a,b):
    global s
    assert a in s, a
    s=s.replace(a,b,1)
rep('if (!img) return { cover: 1, filter: "", luma: "" };','if (!img) return { cover: 1, filter: "", luma: "", shown: 0 };')
rep('return { cover: inside ? covered / inside : 1, filter: getComputedStyle(img).filter, luma: img.dataset.luma ?? "" };','''// How much of the photo is on screen: object-fit cover crops a portrait on a wide box, and a
    // full-bleed backdrop crops whatever falls off the viewport.
    const fit = getComputedStyle(img).objectFit;
    const scale = fit === "cover" ? Math.max(r.width / img.naturalWidth, r.height / img.naturalHeight) : Math.min(r.width / img.naturalWidth, r.height / img.naturalHeight);
    const drawn = img.naturalWidth * scale * img.naturalHeight * scale;
    const shown = ((P.r - P.l) * (P.b - P.t)) / drawn;
    return {
      cover: inside ? covered / inside : 1,
      filter: getComputedStyle(img).filter,
      luma: img.dataset.luma ?? "",
      shown: Math.min(1, shown),
    };''')
rep('''  const pct = Math.round(m.cover * 1000) / 10;''','''  const pct = Math.round(m.cover * 1000) / 10;
  const shownPct = Math.round(m.shown * 1000) / 10;''')
rep('''rows.push(`${tag}: ${pct}% covered''','''rows.push(`${tag}: ${pct}% covered, ${shownPct}% of the photo on screen''')
rep('''  check(`${tag}: the main button fits''','''  check(`${tag}: the whole photo is on screen (no crop)`, m.shown >= 0.97, `${shownPct}%`);
  check(`${tag}: the main button fits''')
open(p,'w').write(s)
EOF
